222	// openResponseWriter creates a new response writer that may (or may not)
223	// encode the response with encodingName. The returned response writer MUST
224	// be closed after the handler completes.
225	func (enc *Encode) openResponseWriter(encodingName string, w http.ResponseWriter, isConnect bool) *responseWriter {
226		var rw responseWriter
227		return enc.initResponseWriter(&rw, encodingName, w, isConnect)
228	}
229	
230	// initResponseWriter initializes the responseWriter instance
231	// allocated in openResponseWriter, enabling mid-stack inlining.
232	func (enc *Encode) initResponseWriter(rw *responseWriter, encodingName string, wrappedRW http.ResponseWriter, isConnect bool) *responseWriter {
233		if rww, ok := wrappedRW.(*caddyhttp.ResponseWriterWrapper); ok {
234			rw.ResponseWriter = rww
235		} else {
236			rw.ResponseWriter = &caddyhttp.ResponseWriterWrapper{ResponseWriter: wrappedRW}
237		}
238		rw.encodingName = encodingName
239		rw.config = enc
240		rw.isConnect = isConnect
241	
242		return rw
243	}
244	
245	// responseWriter writes to an underlying response writer
246	// using the encoding represented by encodingName and
247	// configured by config.
248	type responseWriter struct {
249		http.ResponseWriter
250		encodingName string
251		w            Encoder
252		config       *Encode
253		statusCode   int
254		wroteHeader  bool
255		incremental  bool
256		isConnect    bool
257		disabled     bool // disable encoding for this response
258	}
259	
260	// WriteHeader stores the status to write when the time comes
261	// to actually write the header.
262	func (rw *responseWriter) WriteHeader(status int) {
263		rw.statusCode = status
264		if status == http.StatusPartialContent {
265			rw.disabled = true // partial representations must not be dynamically re-encoded
266		}
267	
268		h := rw.Header()
269		finalStatus := status < 100 || status > 199
270		if !rw.wroteHeader && finalStatus {
271			rw.incremental = caddyhttp.IsIncremental(h)
272		}
273	
274		// See #5849 and RFC 9110 section 15.4.5 (https://www.rfc-editor.org/rfc/rfc9110.html#section-15.4.5) - 304
275		// Not Modified must have certain headers set as if it was a 200 response, and according to the issue
276		// we would miss the Vary header in this case when compression was also enabled; note that we set this
277		// header in the responseWriter.init() method but that is only called if we are writing a response body
278		if status == http.StatusNotModified && !hasVaryValue(h, "Accept-Encoding") {
279			h.Add("Vary", "Accept-Encoding")
280		}
281	
282		// write status immediately if status is 2xx and the request is CONNECT
283		// since it means the response is successful.
284		// see: https://github.com/caddyserver/caddy/issues/6733#issuecomment-2525058845
285		if rw.isConnect && 200 <= status && status <= 299 {
286			rw.ResponseWriter.WriteHeader(status)
287			rw.wroteHeader = true
288		}
289	
290		// write status immediately when status code is informational
291		// see: https://caddy.community/t/disappear-103-early-hints-response-with-encode-enable-caddy-v2-7-6/23081/5
292		if 100 <= status && status <= 199 {
293			rw.ResponseWriter.WriteHeader(status)
294		}
295	
296		// write header immediately for server-sent events responses and for
297		// responses that ask for incremental forwarding (RFC 10036), since the
298		// body may not be written for a while and the client needs the headers
299		// to establish the stream; see #6293
300		if !rw.wroteHeader && finalStatus &&
301			(rw.incremental || isSSE(h.Get("Content-Type"))) {
302			rw.init()
303			rw.ResponseWriter.WriteHeader(status)
304			rw.wroteHeader = true
305		}
306		if rw.incremental && rw.wroteHeader {
307			// WriteHeader alone may remain buffered by net/http. Incremental
308			// forwarding requires the header section to be sent downstream now.
309			_ = http.NewResponseController(rw.ResponseWriter).Flush()
310		}
311	}
312	
313	func isSSE(contentType string) bool {
314		if len(contentType) < len(sseMediaType) || !strings.EqualFold(contentType[:len(sseMediaType)], sseMediaType) {
315			return false
316		}
317	
318		// After the media type, allow only optional whitespace followed by the
319		// end of the value or a parameter separator, so a longer type such as
320		// "text/event-streamfoo" or garbage like "text/event-stream nonsense"
321		// does not match. TrimLeft on the tail does not allocate.
322		rest := strings.TrimLeft(contentType[len(sseMediaType):], " \t")
323	
324		return rest == "" || rest[0] == ';'
325	}
326	
327	// Match determines, if encoding should be done based on the ResponseMatcher.
328	func (enc *Encode) Match(rw *responseWriter) bool {
329		return enc.Matcher.Match(rw.statusCode, rw.Header())
330	}
331	
332	// FlushError is an alternative Flush returning an error. It delays the actual Flush of the underlying
333	// ResponseWriterWrapper until headers were written.
334	func (rw *responseWriter) FlushError() error {
335		if !rw.wroteHeader && rw.statusCode == 0 && caddyhttp.IsIncremental(rw.Header()) {
336			rw.WriteHeader(http.StatusOK)
337		}
338	
339		// WriteHeader wasn't called and is a CONNECT request, treat it as a success.
340		// otherwise, wait until header is written.
341		if rw.isConnect && !rw.wroteHeader && rw.statusCode == 0 {
342			rw.WriteHeader(http.StatusOK)
343		}
344	
345		if !rw.wroteHeader {
346			// flushing the underlying ResponseWriter will write header and status code,
347			// but we need to delay that until we can determine if we must encode and
348			// therefore add the Content-Encoding header; this happens in the first call
349			// to rw.Write (see bug in #4314)
350			return nil
351		}
352		// also flushes the encoder, if any
353		// see: https://github.com/jjiang-stripe/caddy-slow-gzip
354		if rw.w != nil {
355			err := rw.w.Flush()
356			if err != nil {
357				return err
358			}
359		}
360		//nolint:bodyclose
361		return http.NewResponseController(rw.ResponseWriter).Flush()
362	}
363	
364	// Write writes to the response. If the response qualifies,
365	// it is encoded using the encoder, which is initialized
366	// if not done so already.
367	func (rw *responseWriter) Write(p []byte) (int, error) {
368		// ignore zero data writes, probably head request
369		if len(p) == 0 {
370			return 0, nil
371		}
372	
373		// WriteHeader wasn't called and is a CONNECT request, treat it as a success.
374		// otherwise, determine if the response should be compressed.
375		if rw.isConnect && !rw.wroteHeader && rw.statusCode == 0 {
376			rw.WriteHeader(http.StatusOK)
377		}
378		if !rw.wroteHeader && rw.statusCode == 0 && caddyhttp.IsIncremental(rw.Header()) {
379			if rw.Header().Get("Content-Type") == "" {
380				rw.Header().Set("Content-Type", http.DetectContentType(p))
381			}
382			rw.WriteHeader(http.StatusOK)
383		}
384	
385		// sniff content-type and determine content-length
386		if !rw.wroteHeader && rw.config.MinLength > 0 {
387			var gtMinLength bool
388			if len(p) > rw.config.MinLength {
389				gtMinLength = true
390			} else if cl, err := strconv.Atoi(rw.Header().Get("Content-Length")); err == nil && cl > rw.config.MinLength {
391				gtMinLength = true
392			}
393	
394			if gtMinLength {
395				if rw.Header().Get("Content-Type") == "" {
396					rw.Header().Set("Content-Type", http.DetectContentType(p))
397				}
398				rw.init()
399			}
400		}
401	
402		// before we write to the response, we need to make
403		// sure the header is written exactly once; we do
404		// that by checking if a status code has been set,
405		// and if so, that means we haven't written the
406		// header OR the default status code will be written
407		// by the standard library
408		if !rw.wroteHeader {
409			if rw.statusCode != 0 {
410				rw.ResponseWriter.WriteHeader(rw.statusCode)
411			}
412			rw.wroteHeader = true
413		}
414	
415		var n int
416		var err error
417		if rw.w != nil {
418			n, err = rw.w.Write(p)
419		} else {
420			n, err = rw.ResponseWriter.Write(p)
421		}
422		if err != nil || !rw.incremental {
423			return n, err
424		}
425		return n, rw.FlushError()
426	}
