296	// FinalizeUnmarshalCaddyfile finalizes the Caddyfile parsing which
297	// requires having an httpcaddyfile.Helper to function, to parse subroutes.
298	//
299	// EXPERIMENTAL: Subject to change or removal.
300	func (i *Intercept) FinalizeUnmarshalCaddyfile(helper httpcaddyfile.Helper) error {
301		for _, d := range i.handleResponseSegments {
302			// consume the "handle_response" token
303			d.Next()
304			args := d.RemainingArgs()
305	
306			if len(args) > 1 {
307				return d.Errf("too many arguments for 'handle_response': only a single response matcher name is allowed, but got: %s", args)
308			}
309	
310			var matcher *caddyhttp.ResponseMatcher
311			if len(args) == 1 {
312				// the first arg should always be a matcher.
313				if !strings.HasPrefix(args[0], matcherPrefix) {
314					return d.Errf("must use a named response matcher, starting with '@'")
315				}
316	
317				foundMatcher, ok := i.responseMatchers[args[0]]
318				if !ok {
319					return d.Errf("no named response matcher defined with name '%s'", args[0][1:])
320				}
321				matcher = &foundMatcher
322			}
323	
324			// parse the block as routes
325			handler, err := httpcaddyfile.ParseSegmentAsSubroute(helper.WithDispenser(d.NewFromNextSegment()))
326			if err != nil {
327				return err
328			}
329			subroute, ok := handler.(*caddyhttp.Subroute)
330			if !ok {
331				return helper.Errf("segment was not parsed as a subroute")
332			}
333			i.HandleResponse = append(
334				i.HandleResponse,
335				caddyhttp.ResponseHandler{
336					Match:  matcher,
337					Routes: subroute.Routes,
338				},
339			)
340		}
341	
342		// move the handle_response entries without a matcher to the end.
343		// we can't use sort.SliceStable because it will reorder the rest of the
344		// entries which may be undesirable because we don't have a good
345		// heuristic to use for sorting.
346		withoutMatchers := []caddyhttp.ResponseHandler{}
347		withMatchers := []caddyhttp.ResponseHandler{}
348		for _, hr := range i.HandleResponse {
349			if hr.Match == nil {
350				withoutMatchers = append(withoutMatchers, hr)
351			} else {
352				withMatchers = append(withMatchers, hr)
353			}
354		}
355		i.HandleResponse = append(withMatchers, withoutMatchers...)
356	
357		// clean up the bits we only needed for adapting
358		i.handleResponseSegments = nil
359		i.responseMatchers = nil
360	
361		return nil
362	}
