428	// used to mask ReadFrom method
429	type writerOnly struct {
430		io.Writer
431	}
432	
433	// copied from stdlib
434	const sniffLen = 512
435	
436	// ReadFrom will try to use sendfile to copy from the reader to the response writer.
437	// It's only used if the response writer implements io.ReaderFrom and the data can't be compressed.
438	// It's based on the standard library HTTP/1.1 response writer implementation.
439	// https://github.com/golang/go/blob/f4e3ec3dbe3b8e04a058d266adf8e048bab563f2/src/net/http/server.go#L586
440	func (rw *responseWriter) ReadFrom(r io.Reader) (int64, error) {
441		if rw.incremental || !rw.wroteHeader && caddyhttp.IsIncremental(rw.Header()) {
442			return io.Copy(writerOnly{rw}, r)
443		}
444	
445		rf, ok := rw.ResponseWriter.(io.ReaderFrom)
446		// sendfile can't be used anyway
447		if !ok {
448			// mask ReadFrom to avoid infinite recursion
449			return io.Copy(writerOnly{rw}, r)
450		}
451	
452		var ns int64
453		// try to sniff the content type and determine if the response should be compressed
454		if !rw.wroteHeader && rw.config.MinLength > 0 {
455			var (
456				err error
457				buf [sniffLen]byte
458			)
459			// mask ReadFrom to let Write determine if the response should be compressed
460			ns, err = io.CopyBuffer(writerOnly{rw}, io.LimitReader(r, sniffLen), buf[:])
461			if err != nil || ns < sniffLen {
462				return ns, err
463			}
464		}
465	
466		// the response will be compressed, no sendfile support
467		if rw.w != nil {
468			nr, err := io.Copy(rw.w, r)
469			return nr + ns, err
470		}
471		nr, err := rf.ReadFrom(r)
472		return nr + ns, err
473	}
