		{input: "error", want: zapcore.ErrorLevel},
		{input: "loud", wantErr: true},
	} {
		got, err := parseStreamLogLevel(tc.input)
		if tc.wantErr {
			if err == nil {
				t.Errorf("Test %d: expected an error but got none", i)
			}
