// A websocket over HTTP/2 (RFC 8441 extended CONNECT) is relayed to a
// backend that speaks the HTTP/1.1 upgrade.
func TestExtendedConnectWebsocketOverH2(t *testing.T) {
	tester := caddytest.NewTester(t)
	backend := startStreamBackend(t)

	config := fmt.Sprintf(`{
		skip_install_trust
		admin localhost:2999
		http_port     9080
		https_port    9443
		grace_period  1ns
	}

	localhost:9443 {
		reverse_proxy %s
	}`, backend.addr)
	tester.InitServer(config, "caddyfile")

	tr := &http2.Transport{TLSClientConfig: &tls.Config{InsecureSkipVerify: true}} //nolint:gosec
	defer tr.CloseIdleConnections()

	pr, pw := io.Pipe()
	defer pw.Close()
	req, err := http.NewRequest(http.MethodConnect, "https://localhost:9443/ws", pr)
	if err != nil {
		t.Fatal(err)
	}
	req.Header.Set(":protocol", "websocket")
	req.Header.Set("Sec-WebSocket-Version", "13")

	resp, err := tr.RoundTrip(req)
	if err != nil {
		t.Fatalf("extended CONNECT: %v", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		t.Fatalf("status = %d, want 200", resp.StatusCode)
	}

	for _, msg := range []string{"hello over h2", "and again"} {
		if _, err := io.WriteString(pw, msg); err != nil {
			t.Fatalf("writing to the stream: %v", err)
		}
		buf := make([]byte, len(msg))
		if _, err := io.ReadFull(resp.Body, buf); err != nil {
			t.Fatalf("reading from the stream: %v", err)
		}
		if string(buf) != msg {
			t.Errorf("echoed %q, want %q", buf, msg)
		}
	}
}

